import type { Question } from '../questions';

export const UKPSC_PCS_2025_GENERAL_APTITUDE_CORE_1: Question[] = [
  { id: 'b15-004-apt-q001', section: 'General Aptitude Core', topic: 'Interpersonal skills', difficulty: 'medium', question: 'A team member points out an error in a supervisor\'s draft during a review. What response best supports a healthy working relationship?', options: ['Check the point on its merits, correct the draft if needed, and acknowledge the useful review.', 'Reject the point because of hierarchy.', 'Remove the reviewer from future work.', 'Keep the error to avoid embarrassment.'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Treating feedback according to evidence, rather than rank, encourages accurate work and constructive review.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q002', section: 'General Aptitude Core', topic: 'Percentages', difficulty: 'easy', question: 'In a group, 40% of 150 women and 25% of 120 men use a service. How many people in all use it?', options: ['75', '90', '105', '60'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Women: 0.40×150=60; men: 0.25×120=30; total 90.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q003', section: 'General Aptitude Core', topic: 'Syllogism', difficulty: 'hard', question: 'All field auditors are trained officers. Some trained officers are data analysts. No data analyst is a contractor. Which conclusion necessarily follows?', options: ['All field auditors are data analysts.', 'Some trained officers are not contractors.', 'No trained officer is a contractor.', 'Some contractors are data analysts.'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The trained officers who are data analysts are, by the third statement, not contractors; therefore some trained officers are not contractors.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q004', section: 'General Aptitude Core', topic: 'Algebraic constraints', difficulty: 'easy', question: 'A temperature-control reading x is accepted only if it differs from 18°C by no more than 2.5°C. Which interval contains exactly all acceptable values of x?', options: ['15.5°C ≤ x ≤ 20.5°C', '16°C ≤ x ≤ 20°C', 'x ≤ 15.5°C or x ≥ 20.5°C', '18°C ≤ x ≤ 20.5°C'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The condition is |x−18| ≤ 2.5. Therefore −2.5 ≤ x−18 ≤ 2.5, which gives 15.5 ≤ x ≤ 20.5.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q005', section: 'General Aptitude Core', topic: 'Decision making', difficulty: 'medium', question: 'A building inspection identifies two defects: a jammed emergency-exit door that must be corrected before the hall can legally reopen, and peeling paint in an unused store room. Funds today are enough for only one repair. What should be prioritized?', options: ['Paint the store room first because it is cheaper.', 'Reopen the hall without repairing either defect.', 'Split the money so neither repair can be completed.', 'Repair the emergency-exit door first and schedule the cosmetic repair later.'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The exit-door defect is a stated legal and safety condition for reopening, whereas the paint defect is cosmetic and can be deferred.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q006', section: 'General Aptitude Core', topic: 'Comprehension', difficulty: 'medium', question: 'A training centre offered recorded lessons to workers on rotating shifts. Completion increased mainly among workers who had previously missed live sessions because of timing conflicts.\n\nWhich explanation best fits the evidence?', options: ['Recorded lessons reduced the total number of workers.', 'Timing conflicts increased after recordings were introduced.', 'Recorded lessons reduced a scheduling barrier for workers who could not attend at fixed times.', 'All workers prefer recordings to every form of live teaching.'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The improvement is concentrated among those previously constrained by fixed session times.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q007', section: 'General Aptitude Core', topic: 'Remainders', difficulty: 'easy', question: 'What is the smallest positive integer that leaves remainder 2 when divided by 5 and remainder 3 when divided by 7?', options: ['12', '22', '31', '17'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Numbers 2 mod 5 are 2,7,12,17,…; 17 gives remainder 3 on division by 7.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q008', section: 'General Aptitude Core', topic: 'Decision making and prioritization', difficulty: 'hard', question: 'After a cloudburst, a control room has one field team free for the next hour. Report A concerns a blocked road with an ambulance waiting; Report B concerns a damaged signboard on an otherwise open road. The emergency protocol gives first priority to immediate threats to life and access for emergency services. What should the controller do?', options: ['Send the team first to clear the ambulance route, while logging the signboard repair for subsequent action.', 'Repair the signboard first because it was reported earlier.', 'Split the team even if neither task can then be completed safely.', 'Wait until both reports become equally severe.'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The protocol explicitly prioritizes immediate threats to life and emergency-service access, so the blocked ambulance route comes first.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q009', section: 'General Aptitude Core', topic: 'Averages', difficulty: 'easy', question: 'The reported average duration of five inspections was 24 minutes. Later, one duration entered as 32 minutes was found to be 22 minutes. What is the corrected average duration?', options: ['24', '26', '20', '22'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The reported total was 5×24=120 minutes. Correcting 32 to 22 reduces the total by 10 to 110, so the corrected average is 110/5 = 22 minutes.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q010', section: 'General Aptitude Core', topic: 'Quantitative reasoning', difficulty: 'hard', question: 'A number is increased by 8, doubled, and then reduced by 6 to give 50. What is the number?', options: ['16', '22', '20', '24'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: '2(x+8)−6=50 gives 2x=40, so x=20.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q011', section: 'General Aptitude Core', topic: 'Inference', difficulty: 'hard', question: 'A depot added a morning maintenance check. Breakdowns fell, but fuel type, route length and fleet size also changed during the same month. Which inference is strongest?', options: ['The maintenance check definitely caused the entire fall.', 'Fuel type cannot affect breakdowns.', 'Route length stayed constant.', 'The data do not isolate the maintenance check as the sole cause of fewer breakdowns.'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Several conditions changed simultaneously, so the observed decline cannot uniquely identify one cause.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q012', section: 'General Aptitude Core', topic: 'Decision making', difficulty: 'hard', question: 'A public service centre receives an anonymous allegation against an employee. The allegation contains specific transaction numbers that can be checked. What is the best initial action?', options: ['Treat anonymity as proof that the allegation is false.', 'Punish the employee immediately.', 'Publish the allegation before checking it.', 'Verify the cited records objectively before drawing conclusions about the employee.'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Specific verifiable details justify checking the records, but an allegation alone is not a finding.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q013', section: 'General Aptitude Core', topic: 'Communication skills', difficulty: 'medium', question: 'A safety message must be understood by workers with mixed literacy levels. Which design is most appropriate?', options: ['Use only dense legal wording.', 'Use symbols whose meaning has never been explained.', 'Pair brief plain-language instructions with clear symbols and demonstrate the action in person.', 'Give different safety rules to different literacy groups.'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Plain language, interpretable visuals and demonstration provide multiple consistent ways to understand the same safety action.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q014', section: 'General Aptitude Core', topic: 'Decision logic', difficulty: 'medium', question: 'A rule says a request is fast-tracked only if it is both urgent and complete. Request X is urgent but incomplete. What follows?', options: ['X must be fast-tracked because urgency alone is enough.', 'X should not be fast-tracked under this rule.', 'Completeness is irrelevant.', 'The rule says X must be rejected permanently.'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The rule requires both conditions; urgency without completeness does not satisfy it.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q015', section: 'General Aptitude Core', topic: 'Comprehension and indicator selection', difficulty: 'medium', question: 'A spring-restoration project counted both the number of trenches dug and the dry-season discharge measured at village springs. One site dug fewer trenches than another but showed a larger sustained increase in dry-season discharge.\n\nWhat does this example illustrate?', options: ['Activity counts always measure outcomes better than field observations.', 'A direct outcome indicator can show results that the quantity of activities alone does not capture.', 'Digging fewer trenches always produces more water.', 'Spring discharge cannot be measured meaningfully.'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The number of trenches is an activity measure, whereas dry-season discharge directly reflects the intended water outcome.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q016', section: 'General Aptitude Core', topic: 'Work rate', difficulty: 'hard', question: 'A clerk completes 1/5 of a file batch each morning and 1/10 each afternoon. At that rate, on which working day is the batch first completed?', options: ['Day 3', 'Day 5', 'Day 6', 'Day 4'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'One full day completes 3/10. After 3 days, 9/10 is done; the fourth morning completes the remaining 1/10, so the batch is first completed on day 4.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q017', section: 'General Aptitude Core', topic: 'Pattern recognition', difficulty: 'hard', question: 'A sequence is formed by alternately adding 3 and then doubling: 4, 7, 14, 17, 34, 37, … What is the next term?', options: ['40', '68', '74', '77'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The operations repeat +3, ×2. After 34+3=37, the next operation is ×2, giving 74.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q018', section: 'General Aptitude Core', topic: 'Conditional reasoning', difficulty: 'hard', question: 'If a file is confidential, it must be encrypted. If it is encrypted, it must be stored on the secure server. File F is confidential. What must be true?', options: ['F must be stored on the secure server.', 'F cannot be encrypted.', 'F must be public.', 'F may be stored only on a personal device.'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Confidential → encrypted and encrypted → secure server, so by chaining the conditions, F must be on the secure server.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q019', section: 'General Aptitude Core', topic: 'Problem solving', difficulty: 'medium', question: 'A team must choose two of four repairs. Repair A prevents 9 expected service failures, B prevents 7, C prevents 6 and D prevents 3. A and B cannot be done together. Which allowed pair prevents the most expected failures?', options: ['A and D', 'B and C', 'A and C', 'B and D'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Allowed totals are A+C=15, A+D=12, B+C=13 and B+D=10. The maximum is 15.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q020', section: 'General Aptitude Core', topic: 'Ratio and proportion', difficulty: 'easy', question: 'A recipe uses grain and pulses in the ratio 7:2. If 18 kg of pulses are used, how much grain is needed?', options: ['49 kg', '56 kg', '63 kg', '72 kg'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Each 2 parts of pulses correspond to 7 parts grain, so grain=18×7/2=63 kg.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q021', section: 'General Aptitude Core', topic: 'Ranking with partial order', difficulty: 'medium', question: 'In a trek timing table, P finished before Q. R finished after Q but before S. Which statement must be true?', options: ['P finished before R.', 'S finished before P.', 'R finished before Q.', 'Q finished after S.'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The relations are P<Q<R<S, so P must have finished before R.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q022', section: 'General Aptitude Core', topic: 'Clock reasoning', difficulty: 'medium', question: 'A 24-hour digital clock shows 13:31. After how many minutes will it next show a time whose four digits read the same forward and backward?', options: ['30 minutes', '60 minutes', '110 minutes', '70 minutes'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The next palindromic display after 13:31 is 14:41. The interval from 13:31 to 14:41 is 70 minutes.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q023', section: 'General Aptitude Core', topic: 'Comprehension and constrained planning', difficulty: 'hard', question: 'A snow-clearance unit has two ploughs. The morning plan clears one route to the hospital and one route to the food depot before residential lanes. Overnight snowfall blocks all routes equally, but the hospital route also carries the district\'s only oxygen-supply vehicle at 8 a.m.\n\nWhich scheduling principle is most strongly supported by the information?', options: ['Residential lanes should always be cleared before institutional routes.', 'All routes should be chosen randomly because snowfall was equal.', 'The food-depot route can never be important.', 'When resources are limited, time-critical consequences can justify prioritizing one route even when physical blockage is similar.'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The blockage is similar, but the hospital route has an additional time-critical consequence, so consequence-based priority is justified.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q024', section: 'General Aptitude Core', topic: 'Ages', difficulty: 'medium', question: 'The present age ratio of P to Q is 4:5. Eight years from now the ratio will be 6:7. What is P\'s present age?', options: ['12 years', '16 years', '20 years', '24 years'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Let ages 4x,5x. (4x+8)/(5x+8)=6/7 gives 28x+56=30x+48, so x=4 and P=16.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q025', section: 'General Aptitude Core', topic: 'Scheduling', difficulty: 'hard', question: 'Four 30-minute interviews A, B, C and D must fill slots 10:00, 10:30, 11:00 and 11:30. A must be before C; B must be immediately after C; D cannot be first. Which schedule works?', options: ['10:00 D, 10:30 A, 11:00 C, 11:30 B', '10:00 A, 10:30 B, 11:00 C, 11:30 D', '10:00 C, 10:30 B, 11:00 A, 11:30 D', '10:00 A, 10:30 C, 11:00 B, 11:30 D'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'A must precede C, B must immediately follow C, and D cannot be first. Only A,C,B,D satisfies all three.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q026', section: 'General Aptitude Core', topic: 'Process reasoning', difficulty: 'medium', question: 'A signal controller cycles through Red → Amber → Green → Red, advancing one state after each completed check. It is on Amber before any checks. What state is it on after 8 checks?', options: ['Green', 'Amber', 'Cannot be determined', 'Red'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The states repeat every three checks. Eight checks are two steps beyond a multiple of three; from Amber, two advances give Green and then Red.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q027', section: 'General Aptitude Core', topic: 'Probability without replacement', difficulty: 'medium', question: 'A bag contains 5 white and 3 black tokens. Two tokens are drawn one after another without replacement. What is the probability that both are black?', options: ['3/8', '9/64', '3/28', '1/4'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The probability is (3/8)×(2/7)=6/56=3/28.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q028', section: 'General Aptitude Core', topic: 'Interpersonal communication', difficulty: 'medium', question: 'A field supervisor gives a safety instruction over a noisy radio link. Which response best uses closed-loop communication?', options: ['Remain silent to avoid delaying the work.', 'Say only \'okay\' even if part of the instruction was unclear.', 'Ask another worker later what the supervisor might have meant.', 'Repeat the critical instruction back in your own words and obtain confirmation or correction.'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Closed-loop communication requires the receiver to restate the critical message and the sender to confirm or correct it.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q029', section: 'General Aptitude Core', topic: 'Average speed', difficulty: 'hard', question: 'A cyclist covers one-third of a 90 km route at 15 km/h and the rest at 30 km/h. What is the average speed?', options: ['20 km/h', '24 km/h', '25 km/h', '22.5 km/h'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: '30 km takes 2 h; 60 km takes 2 h; total 90 km in 4 h gives 22.5 km/h.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q030', section: 'General Aptitude Core', topic: 'Comprehension and service outcomes', difficulty: 'medium', question: 'A mobile service van increased the number of village visits from four to six per month. Total transactions rose, but the share of visitors who had to return because a required document was missing did not change.\n\nWhich conclusion is best supported?', options: ['Increasing visit frequency improved access volume but did not, by itself, reduce document-related repeat visits.', 'More visits necessarily improved document guidance.', 'The van should stop visiting villages.', 'Every additional transaction was a repeat visit.'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Transactions increased with more visits, while the document-related return rate stayed unchanged, so the access-volume effect did not solve that separate problem.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q031', section: 'General Aptitude Core', topic: 'Trains', difficulty: 'medium', question: 'Two trains of lengths 150 m and 100 m move in opposite directions at 45 km/h and 27 km/h. How long from front-to-front meeting until they completely cross?', options: ['10 seconds', '12.5 seconds', '15 seconds', '20 seconds'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Relative speed=72 km/h=20 m/s; total length=250 m; time=12.5 s.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q032', section: 'General Aptitude Core', topic: 'Number series', difficulty: 'medium', question: 'For a mountain-district analytical exercise, Find the next term in the series 3, 7, 15, 31, … Use the supplied values as the complete information for the calculation.', options: ['55', '47', '62', '63'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Each term is twice the previous term plus 1: 3→7→15→31→63.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q033', section: 'General Aptitude Core', topic: 'Number system', difficulty: 'easy', question: 'What is the least positive number divisible by 8, 12 and 18?', options: ['36', '72', '48', '144'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'LCM: 8=2³, 12=2²×3, 18=2×3², so LCM=2³×3²=72.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q034', section: 'General Aptitude Core', topic: 'Comprehension', difficulty: 'medium', question: 'A municipal team received many reports that streetlights were \'not working\'. It separated reports into power-supply faults, broken lamps and timer-setting problems. Repair time fell because crews could take the right tools on the first visit.\n\nWhat made the new reporting system useful?', options: ['It ensured that every streetlight had the same fault.', 'It made repair crews carry every possible tool.', 'It converted a broad complaint into categories that guided different repair actions.', 'It removed the need to inspect reported faults.'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Categorization links the reported problem to the likely repair need, improving preparation.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q035', section: 'General Aptitude Core', topic: 'Comprehension', difficulty: 'medium', question: 'A scholarship office published both the selection criteria and anonymized examples of how borderline cases were assessed. Appeals then focused more often on specific criteria rather than general suspicion.\n\nWhich effect is most plausibly described?', options: ['Transparency eliminated every possible disagreement.', 'Publishing examples replaced the need for selection criteria.', 'Anonymization made the criteria secret.', 'Greater transparency helped applicants frame disagreements around the stated rules.'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The change supplied applicants with the decision framework, so appeals became more rule-specific.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q036', section: 'General Aptitude Core', topic: 'Data quality and verification', difficulty: 'hard', question: 'A survey app rejects ages above 120 and flags households reporting zero members. After these checks were introduced, impossible values fell, but duplicate household records still appeared at the same rate.\n\nWhat does the evidence show?', options: ['Range checks remove every kind of data error.', 'Duplicate records are caused only by ages above 120.', 'The app should accept impossible ages to find duplicates.', 'The new validation rules addressed some value-level errors but did not address record duplication.'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The checks target implausible field values and zero-member entries; unchanged duplication shows that a different control is needed for duplicate records.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q037', section: 'General Aptitude Core', topic: 'Elevation arithmetic', difficulty: 'medium', question: 'A survey team starts at an elevation of 1,240 metres. It climbs 180 metres, descends 75 metres, and then climbs 40 metres. What is its final elevation?', options: ['1,345 m', '1,365 m', '1,385 m', '1,435 m'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: '1,240 + 180 − 75 + 40 = 1,385 metres.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q038', section: 'General Aptitude Core', topic: 'Mensuration', difficulty: 'medium', question: 'A square courtyard has area 784 m². A path goes once around its boundary. What distance is one complete round?', options: ['112 m', '56 m', '28 m', '196 m'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Side =√784=28 m, so perimeter =4×28=112 m.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q039', section: 'General Aptitude Core', topic: 'Probability and expectation', difficulty: 'medium', question: 'A fair spinner has four equal sectors labelled 0, 1, 1 and 4. What is the expected score from one spin?', options: ['1', '1.5', '2', '2.5'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Each sector is equally likely, so the expected score is (0+1+1+4)/4 = 6/4 = 1.5.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q040', section: 'General Aptitude Core', topic: 'Classification', difficulty: 'easy', question: 'Which pair differs in relationship from the others?', options: ['Square : Cube', 'Circle : Cylinder', 'Triangle : Sphere', 'Rectangle : Cuboid'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The other pairs relate a plane shape to a solid that can have that shape as a face/base; a sphere has no triangular face or base.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q041', section: 'General Aptitude Core', topic: 'Number series', difficulty: 'medium', question: 'Find the next term in the sequence: 2, 5, 11, 20, 32, …', options: ['44', '47', '50', '52'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The successive differences are 3, 6, 9 and 12; the next difference is 15, giving 32+15=47.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q042', section: 'General Aptitude Core', topic: 'Problem solving', difficulty: 'medium', question: 'A report contains 12 pages. Pages 1–4 are approved, pages 5–9 need checking, and pages 10–12 are approved. If two checking pages are cleared, how many pages still need checking?', options: ['2', '5', '7', '3'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Five pages initially need checking (5 through 9). Clearing two leaves 3.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q043', section: 'General Aptitude Core', topic: 'Geometry and scaling', difficulty: 'medium', question: 'A rectangular map panel is 18 cm long and 12 cm wide. It is enlarged so that every length is multiplied by 1.5. What is the area of the enlarged panel?', options: ['324 cm²', '486 cm²', '432 cm²', '540 cm²'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Original area = 18×12 = 216 cm². Area scales by 1.5²=2.25, so the new area is 216×2.25 = 486 cm².', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q044', section: 'General Aptitude Core', topic: 'Data interpretation', difficulty: 'medium', question: 'A clinic recorded waiting times of 8, 10, 10, 12, 15, 18 and 27 minutes. What is the interquartile range using the medians of the lower and upper three values?', options: ['6 minutes', '8 minutes', '10 minutes', '12 minutes'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'For the lower half [8,10,10], Q1=10. For the upper half [15,18,27], Q3=18. Thus IQR=18−10=8 minutes.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q045', section: 'General Aptitude Core', topic: 'Data interpretation', difficulty: 'easy', question: 'A store\'s four categories have stock: A 90, B 60, C 120, D 30. What fraction of total stock is category C?', options: ['1/3', '1/4', '2/5', '1/2'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Total=300; C=120, so 120/300=2/5.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q046', section: 'General Aptitude Core', topic: 'Letter-number coding', difficulty: 'medium', question: 'Using A=1, B=2, …, Z=26, a code is formed by adding the letter values. What is the value of the word HILL?', options: ['37', '41', '45', '49'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'HILL = 8+9+12+12 = 41.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q047', section: 'General Aptitude Core', topic: 'Counting', difficulty: 'medium', question: 'A four-digit PIN uses digits 0–9, repetition allowed, but the first digit cannot be 0. How many PINs are possible?', options: ['1,000', '9,999', '9,000', '10,000'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'First digit has 9 choices; each remaining digit has 10, so 9×10³=9,000.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q048', section: 'General Aptitude Core', topic: 'Boats and streams', difficulty: 'easy', question: 'A boat takes 2 hours to travel 30 km downstream and 3 hours to return the same distance upstream. What is the speed of the stream?', options: ['2 km/h', '3 km/h', '2.5 km/h', '5 km/h'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Downstream speed=15, upstream=10. Stream speed=(15−10)/2=2.5 km/h.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q049', section: 'General Aptitude Core', topic: 'Problem solving', difficulty: 'medium', question: 'A service van must carry 600 kg or less. It already carries 355 kg. Three crates weigh 80 kg each. How many of the crates can be added without exceeding the limit?', options: ['1', '3', '2', '0'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'All three add 240 kg, giving 595 kg, which is within the 600 kg limit.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q050', section: 'General Aptitude Core', topic: 'Comprehension', difficulty: 'medium', question: 'For a hill-transport planning exercise, A records unit tested two scanning workflows for a month. The second workflow reduced average processing time, but the error rate and staffing level stayed almost unchanged. The unit adopted the second workflow and retained the same quality checks.\n\nWhich inference follows most directly from the evidence?\n\nNo other process change is recorded during the interval described in this account. Treat the stated observations as the complete evidence for this question and select the strongest supported inference.', options: ['The second workflow improved speed without evidence of a quality trade-off in the trial.', 'The second workflow eliminated all errors.', 'More staff caused the improvement.', 'Quality checks are no longer necessary.'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The answer follows from the central relationship stated in the passage.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q051', section: 'General Aptitude Core', topic: 'Relative speed', difficulty: 'medium', question: 'A bus moving at 70 km/h overtakes a truck moving in the same direction at 50 km/h. If the bus is 200 m behind the truck initially, how long until it catches the truck?', options: ['36 seconds', '18 seconds', '24 seconds', '72 seconds'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Relative speed=20 km/h=5.556 m/s. Time=200/5.556≈36 s.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q052', section: 'General Aptitude Core', topic: 'Comprehension and behavioural response', difficulty: 'medium', question: 'A district sends appointment reminders by SMS 48 hours before scheduled health visits. Missed appointments fall, but average consultation time and treatment protocol remain unchanged.\n\nWhich inference is strongest?', options: ['SMS reminders made consultations medically shorter.', 'The reminders likely affected attendance behaviour rather than the clinical process itself.', 'Treatment protocols caused the reduction in missed appointments.', 'Every patient reads every reminder.'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The attendance outcome changed while clinical timing and protocol did not, which supports a behavioural attendance effect rather than a change in treatment.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q053', section: 'General Aptitude Core', topic: 'Communication skills', difficulty: 'hard', question: 'An email thread contains several unrelated decisions. A new member joins the project. What should the coordinator send?', options: ['A current summary organized by issue, stating the latest decision and next action for each.', 'The entire thread with no indication of which messages are obsolete.', 'Only the oldest email in the thread.', 'A list of sender names without decisions.'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'A current issue-based summary reduces the risk that an outdated message is mistaken for the latest decision.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q054', section: 'General Aptitude Core', topic: 'Problem solving', difficulty: 'hard', question: 'A team has to inspect 5 sites. It can inspect at most 2 sites per day, and site E must be inspected alone because it needs a full-day specialist. What is the minimum number of days?', options: ['3', '2', '4', '5'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'E uses one full day. The remaining four sites can be done two per day in two more days, for a minimum of three.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q055', section: 'General Aptitude Core', topic: 'Interpersonal skills', difficulty: 'hard', question: 'A colleague is upset after a difficult citizen interaction and starts describing it angrily. What is the best immediate response?', options: ['Match the colleague\'s anger to show support.', 'Share the citizen\'s personal details with unrelated coworkers.', 'Promise an outcome before checking the facts.', 'Listen briefly, acknowledge the concern, then move the discussion toward facts and the next appropriate action.'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Acknowledging emotion while returning to facts and appropriate action supports the colleague without escalating or prejudging the case.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q056', section: 'General Aptitude Core', topic: 'Binary logic', difficulty: 'medium', question: 'A gate opens if and only if either card P or card Q is valid, but not both. P is valid and the gate does not open. What follows?', options: ['Q is invalid.', 'Q is also valid.', 'P is invalid.', 'Neither card is valid.'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'With exclusive-or, P valid and Q invalid would open the gate. Since it does not, Q must also be valid, making both valid.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q057', section: 'General Aptitude Core', topic: 'Comprehension', difficulty: 'medium', question: 'A bus operator found that one route was often late only on market days. Instead of increasing scheduled travel time every day, it added extra time only to market-day trips.\n\nWhat principle does this response illustrate?', options: ['Match the remedy to the condition under which the delay actually occurs.', 'Apply the most disruptive remedy to all days.', 'Ignore a recurring pattern unless it happens daily.', 'Assume market-day and non-market-day traffic are identical.'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The operator targets the adjustment to the days associated with the observed delay rather than imposing it universally.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q058', section: 'General Aptitude Core', topic: 'Clock and time reasoning', difficulty: 'medium', question: 'A 24-hour control room logs an inspection at 21:35. The next inspection occurs 7 hours 50 minutes later. At what time does it occur?', options: ['05:25', '04:25', '05:15', '06:25'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: '21:35 + 7 hours = 04:35 the next day; adding 50 minutes gives 05:25.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q059', section: 'General Aptitude Core', topic: 'Ordering', difficulty: 'medium', question: 'Five runners P, Q, R, S and T finish a race. P is before Q, R is immediately after P, and S is last. Which order is possible?', options: ['P, Q, R, T, S', 'T, R, P, Q, S', 'T, P, R, Q, S', 'P, R, S, T, Q'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'P must be followed immediately by R, P before Q, and S last. Only T,P,R,Q,S meets all conditions.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q060', section: 'General Aptitude Core', topic: 'Sets and Venn diagrams', difficulty: 'medium', question: 'Of 120 applicants, 70 have degree A, 55 have degree B, and 15 have neither. How many have both degrees?', options: ['20', '5', '15', '25'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'At least one=105. Both=70+55−105=20.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q061', section: 'General Aptitude Core', topic: 'Constraint reasoning', difficulty: 'hard', question: 'Three deliveries X, Y and Z use one vehicle. X must occur before Y; Z cannot be last; Y cannot be first. Which order is valid?', options: ['Y, X, Z', 'Z, Y, X', 'Y, Z, X', 'X, Z, Y'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'X before Y and Z not last are both satisfied only by X,Z,Y among the choices.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q062', section: 'General Aptitude Core', topic: 'Recursive series', difficulty: 'medium', question: 'A sequence begins 3, 5, 8, 12, 17, …, where the amounts added are 2, 3, 4, 5, … What is the next term?', options: ['21', '22', '23', '24'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The next increment is 6, so the next term is 17+6=23.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q063', section: 'General Aptitude Core', topic: 'Set reasoning', difficulty: 'medium', question: 'All emergency vehicles are authorized vehicles. No unauthorized vehicle may enter Gate A. Which conclusion is guaranteed about emergency vehicles?', options: ['They must enter Gate A every day.', 'They may ignore every gate rule.', 'They are not excluded from Gate A for being unauthorized.', 'No authorized vehicle can enter Gate A.'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Emergency vehicles are authorized, so the rule excluding unauthorized vehicles does not exclude them on that ground.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q064', section: 'General Aptitude Core', topic: 'Comprehension', difficulty: 'medium', question: 'A public dashboard showed total complaints received by each ward. A ward with the highest total also had by far the largest population. The dashboard was revised to show complaints per thousand residents as well.\n\nWhat limitation of the original display was addressed?', options: ['Raw totals did not account for large differences in the population served.', 'Complaint totals cannot be counted.', 'Population size can never affect service comparisons.', 'Rates are useful only when all wards have equal populations.'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Adding a population-adjusted rate helps separate service volume from the size of the population base.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q065', section: 'General Aptitude Core', topic: 'Decision making under uncertainty', difficulty: 'hard', question: 'A mountain rescue coordinator receives an unverified message that a trekking group may be stranded beyond a pass. Weather is worsening, and the protocol says potential life-threatening reports must be promptly verified while a response team is placed on standby. What is the best immediate action?', options: ['Ignore the message until a formal written complaint arrives.', 'Begin rapid verification and place the response team on standby as the protocol requires.', 'Deploy every available team without any attempt to verify location or need.', 'Publicly announce that the group is safe because the report is unverified.'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The protocol requires two parallel actions: prompt verification and readiness to respond, avoiding both neglect and uncontrolled deployment.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q066', section: 'General Aptitude Core', topic: 'Deductive reasoning', difficulty: 'medium', question: 'Every permit with code Z requires supervisor review. Permit P has code Z. Which conclusion follows?', options: ['Permit P is already approved.', 'Only code Z permits need review.', 'Permit P requires supervisor review.', 'Supervisor review guarantees approval.'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'P satisfies the sufficient condition \'has code Z\', so the stated rule requires supervisor review.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q067', section: 'General Aptitude Core', topic: 'Odd relationship', difficulty: 'easy', question: 'Which pair is unlike the others?', options: ['Egg : Bird', 'Seed : Metal', 'Larva : Insect', 'Bud : Flower'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The other pairs relate an early biological stage to a later form; seed and metal do not.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q068', section: 'General Aptitude Core', topic: 'Interpersonal skills', difficulty: 'medium', question: 'A cross-functional group keeps missing tasks because members assume someone else is handling them. Which intervention most directly addresses the problem?', options: ['Add more attendees without assigning work.', 'Avoid written action lists.', 'End each meeting with named owners and due dates for every agreed action.', 'Allow each task to have several unnamed owners.'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Named ownership and deadlines remove ambiguity about responsibility.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q069', section: 'General Aptitude Core', topic: 'Comprehension', difficulty: 'medium', question: 'A laboratory introduced a checklist for specimen labeling. Errors fell, but the supervisor kept occasional audits because a checklist can be skipped or followed mechanically.\n\nWhy retain the audits?', options: ['A preventive control does not remove the need to verify that the control itself is being used effectively.', 'Audits prove the checklist is unnecessary.', 'A checklist guarantees perfect compliance forever.', 'Labeling errors are impossible to detect after collection.'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The audit provides independent verification that the checklist is actually used and works as intended.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q070', section: 'General Aptitude Core', topic: 'Speed, distance and time', difficulty: 'medium', question: 'Two towns are 270 km apart. A car covers the first 90 km at 45 km/h. What speed is needed for the remaining 180 km to complete the entire trip in 5 hours?', options: ['45 km/h', '60 km/h', '54 km/h', '72 km/h'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'First leg takes 2 h, leaving 3 h for 180 km; required speed=60 km/h.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q071', section: 'General Aptitude Core', topic: 'Logical reasoning', difficulty: 'medium', question: 'Five distinct files are placed into four drawers, with every file in exactly one drawer. Which statement must be true?', options: ['Every drawer contains at least one file.', 'Exactly one drawer contains two files.', 'At least one drawer contains at least two files.', 'One drawer must contain all five files.'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'With five files placed among only four drawers, the pigeonhole principle guarantees that at least one drawer contains two or more files.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q072', section: 'General Aptitude Core', topic: 'Arrangement with adjacency constraints', difficulty: 'hard', question: 'Four teams P, Q, R and S sit around a square table, one on each side. P must sit opposite R. Q must sit immediately clockwise of R. Which arrangement is possible, reading clockwise from P?', options: ['P, Q, R, S', 'P, S, Q, R', 'P, R, S, Q', 'P, S, R, Q'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Starting from P, R must be two positions later. If Q is immediately clockwise of R, the order is P, S, R, Q.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q073', section: 'General Aptitude Core', topic: 'Comprehension', difficulty: 'medium', question: 'A department merged two application forms that asked for many of the same details. The new form had one common section and short service-specific sections. Completion errors fell.\n\nWhich design improvement is described?', options: ['Delete all service-specific information.', 'Require applicants to complete both old forms as well.', 'Replace written information with unstated assumptions.', 'Remove repeated data entry while retaining fields needed for different services.'], correctIndex: 3, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The merged form reduces duplication without discarding information unique to each service.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q074', section: 'General Aptitude Core', topic: 'Algebra', difficulty: 'easy', question: 'Two numbers have sum 26 and difference 8. What is the larger number?', options: ['17', '9', '13', '18'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Let the larger number be x and the smaller y. x+y=26 and x−y=8; adding gives 2x=34, so x=17.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q075', section: 'General Aptitude Core', topic: 'Communication skills', difficulty: 'hard', question: 'A public notice says an office will be \'closed briefly\' for maintenance. Residents need to plan visits. Which revision is best?', options: ['Keep \'briefly\' without dates.', 'Add more adjectives but no operational details.', 'State the exact closure date and hours, affected services, and any available alternative channel.', 'Remove mention of maintenance and closure.'], correctIndex: 2, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Planning requires precise timing, scope and alternatives rather than a vague duration.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q076', section: 'General Aptitude Core', topic: 'Comprehension', difficulty: 'medium', question: 'A flood-warning group sends a technical bulletin to engineers and a short action message to village volunteers. Both messages are based on the same forecast, but each uses detail suited to the audience\'s task.\n\nWhat communication principle is illustrated?', options: ['Keep the underlying information consistent while adapting detail and format to the audience\'s needs.', 'Give different factual forecasts to different audiences.', 'Use maximum technical detail for every reader.', 'Avoid action instructions in emergency communication.'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The same underlying forecast is expressed differently because engineers and volunteers need different levels of detail.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q077', section: 'General Aptitude Core', topic: 'Arithmetic and unit conversion', difficulty: 'medium', question: 'A water tank receives 2.4 kilolitres and then 650 litres. How many litres are in the tank from these two additions?', options: ['2,450 litres', '3,050 litres', '3,650 litres', '24,650 litres'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: '2.4 kilolitres = 2,400 litres. Adding 650 litres gives 3,050 litres.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q078', section: 'General Aptitude Core', topic: 'Digit formation', difficulty: 'medium', question: 'How many two-digit even numbers can be formed from the digits 1, 2, 3 and 4 without repeating a digit?', options: ['6', '4', '8', '12'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'The units digit must be 2 or 4 (2 choices). For each choice, the tens digit can be any of the remaining 3 digits, giving 2×3=6 numbers.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q079', section: 'General Aptitude Core', topic: 'Data interpretation', difficulty: 'medium', question: 'A district\'s service completion rates are: North 84% of 500 cases, South 90% of 300, East 80% of 400. Which district completed the greatest number of cases?', options: ['South', 'North', 'East', 'North and East are equal'], correctIndex: 1, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Completed: North 420, South 270, East 320. North is highest.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
  { id: 'b15-004-apt-q080', section: 'General Aptitude Core', topic: 'Comprehension', difficulty: 'medium', question: 'An archive photographed fragile maps before allowing researchers to handle them. Requests for the originals fell, but originals remained available when fine physical details were needed.\n\nWhat approach does the archive take?', options: ['Use a lower-risk substitute for routine access while preserving the original for cases that genuinely require it.', 'Destroy originals once photographs exist.', 'Ban all research use of the maps.', 'Assume photographs capture every physical property of an original.'], correctIndex: 0, answerType: 'mcq', marks: 1.5, negativeMarking: 0.375, explanation: 'Digital images handle routine needs and reduce wear, while originals remain available for purposes the images cannot satisfy.', source: { kind: 'original', reference: 'UKPSC official Combined State Civil/Upper Subordinate Services scheme', url: 'https://psc.uk.gov.in/public/uploads/syllabus/746895957.pdf', checkedOn: '2026-09-10' } },
];
